fun {Seller} {Rating} [Fintype Rating] [DecidableEq Rating] M sampleRate hi lo k =>
  have nHi := EconCSLib.Probability.floorSampleCount sampleRate hi k;
  have nLo := EconCSLib.Probability.floorSampleCount sampleRate lo k;
  EconCSLib.Probability.twoSamplePkComplementErrorProb M hi lo nHi nLo (↑nHi)⁻¹ (↑nLo)⁻¹

fun {θ} successProb hprob0 hprob1 =>
  { typeLaw := fun t => EconCSLib.Probability.realBernoulliPMF (successProb t) ⋯ ⋯,
    score := EconCSLib.Probability.binaryRatingScore }

fun {α} {Piece} [MeasurableSpace α] [Fintype Piece] {μ} P selected [DecidablePred selected] =>
  { support := ⋃ piece, P.pieceSet ↑piece, pieceSet := fun piece => P.pieceSet ↑piece, measurable_piece := ⋯,
    pairwiseDisjoint := ⋯, cover := ⋯ }

fun {α} {Piece} [MeasurableSpace α] [Fintype Piece] {μ} {β} {Pieceβ} [MeasurableSpace β] [Fintype Pieceβ] {ν} P Q =>
  { support := P.support ×ˢ Q.support, pieceSet := fun piece => P.pieceSet piece.1 ×ˢ Q.pieceSet piece.2,
    measurable_piece := ⋯, pairwiseDisjoint := ⋯, cover := ⋯ }

fun μ n cut hmono =>
  { support := Set.Ioc (cut 0) (cut n), pieceSet := fun piece => Set.Ioc (cut ↑piece) (cut (↑piece + 1)),
    measurable_piece := ⋯, pairwiseDisjoint := ⋯, cover := ⋯ }

